import{z as o,x as S,o as B,c as i,q as r,j as t,D as A,d as E,s as p,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"OSPF 区域与 LSA","description":"","frontmatter":{"title":"OSPF 区域与 LSA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ospf-areas-lsa.md","filePath":"cs/ospf-areas-lsa.md","lastUpdated":1791413859000}'),n={name:"cs/ospf-areas-lsa.md"};function T(d,a,F,P,D,R){const s=S("Mermaid");return B(),i("div",null,[a[2]||(a[2]=r('<h1 id="ospf-区域与-lsa" tabindex="-1">OSPF 区域与 LSA <a class="header-anchor" href="#ospf-区域与-lsa" aria-label="Permalink to &quot;OSPF 区域与 LSA&quot;">​</a></h1><div class="epigraph"><p>区域把 LSDB 洪泛切成块；不同类型的 LSA 分别描述路由器、网络、汇总与外部，骨干区域把块再连起来。</p><footer>—— 据 Moy, RFC 2328 OSPF Version 2；RFC 5340 OSPFv3 整理</footer></div><p>主干<a href="/cs/ospf-dijkstra">Dijkstra 在 OSPF</a> 已会从 LSDB 算下一跳，区域只点名。<a href="/cs/satellite-latency">上一课</a> 结束无线广域。缺口是<strong>区域与 LSA 类型</strong>：Area 0、stub/NSSA、Type 1–5/7 各描述什么，避免把全网当成一张平坦图。本课不把 IS-IS TLV 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单区域洪泛随路由器数涨，SPF 与 LSDB 内存一起涨。分区：区内 Type 1/2 精确，跨区 Type 3 汇总，外部 Type 5 从 ASBR 进，NSSA 用 Type 7 再转 5。骨干必须连续，否则虚链路——那是补丁，不是拓扑目标。代价仍是管理度量，不是卫星 RTT。</p><p>不要把区域写成 VLAN：VLAN 是二层广播域；区域是 LSDB 范围。</p><p><span class="marginnote">数字实例：假设全网 200 台路由器，单区域时每台的 LSDB 都要装下 200 条 Type 1 加全部 Type 5，SPF 也对全网算；切成 5 个区域后，普通区路由器只存本区约 40 条 Type 1，跨区只剩 ABR 汇总出的几十条 Type 3——计算与内存随区域大小而非全网大小增长。</span></p><p><span class="marginnote">RFC 2328 第 3、12 章。OSPFv3 把 LSA 改到 IPv6 地址族，对象不变。本课不把每一种 Opaque LSA 列完。</span></p><h3 id="区域不是-vlan" tabindex="-1">区域不是 VLAN <a class="header-anchor" href="#区域不是-vlan" aria-label="Permalink to &quot;区域不是 VLAN&quot;">​</a></h3><p>LSDB 范围与广播域是两件事。Type 3 汇总可扩展也可能藏黑洞。虚链路是补丁。度量仍是管理代价，不是卫星 RTT。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：Area 1/2 接 Area 0；ABR 发汇总。对照距离向量：这里仍是链路状态，只是图被切开。ECMP 在等代价多下一跳时仍可用。LACP 逻辑口在 OSPF 里是一条链路。</p>',12)),(B(),t(l,null,{default:A(()=>[p(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22Type1%20%E8%B7%AF%E7%94%B1%E5%99%A8%20LSA%22%5D%20--%3E%20LSDB%5B%22%E5%8C%BA%E5%86%85%20LSDB%22%5D%0A%20%20N%5B%22Type2%20%E7%BD%91%E7%BB%9C%20LSA%22%5D%20--%3E%20LSDB%0A%20%20ABR%5B%22ABR%22%5D%20--%3E%20T3%5B%22Type3%20%E6%B1%87%E6%80%BB%22%5D%0A%20%20ASBR%5B%22ASBR%22%5D%20--%3E%20T5%5B%22Type5%20%E5%A4%96%E9%83%A8%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"MAC 学习不跨区域；IP 前缀跨区域靠汇总。汇总错会黑洞或次优，这是政策，不是 SPF bug。PFC 与 OSPF 无关。主干 BGP 直觉：外部 Type 5 常来自再分发，环与优先级要用 tag 防，细节留给 BGP 课。",-1)),a[5]||(a[5]=e("p",null,"虚链路把 Area 0 的邻接「隧道」过非骨干，增加故障域，能不用则不用。",-1)),a[6]||(a[6]=e("p",null,"一条前缀从外部网到普通区域，路上要换几次「票据」：ASBR 用 Type 5 把外部前缀灌进骨干与非 stub 区域，ABR 再用 Type 4 把「ASBR 在哪、到它多远」递进本区，区内路由器最后用 Type 1/2 的精确信息算出「我先怎么走到 ABR」。三段成本相加才是最终度量——外部段、到 ASBR 的汇总段、区内段，缺一段都到不了。",-1)),(B(),t(l,null,{default:A(()=>[p(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXT%5B%22%E5%A4%96%E9%83%A8%E7%BD%91%E7%BB%9C%E5%89%8D%E7%BC%80%22%5D%20--%3E%20ASBR%5B%22ASBR%20%E5%8F%91%20Type5%20%E5%A4%96%E9%83%A8%20LSA%22%5D%0A%20%20ASBR%20--%3E%20FLOOD%5B%22Type5%20%E6%B4%AA%E6%B3%9B%E5%88%B0%E9%AA%A8%E5%B9%B2%E4%B8%8E%E6%99%AE%E9%80%9A%E5%8C%BA%E5%9F%9F%22%5D%0A%20%20FLOOD%20--%3E%20ABR%5B%22Area%201%20%E7%9A%84%20ABR%22%5D%0A%20%20ABR%20--%3E%20T4%5B%22ABR%20%E5%8F%91%20Type4%20%E5%91%8A%E7%9F%A5%20ASBR%20%E5%8F%AF%E8%BE%BE%22%5D%0A%20%20T4%20--%3E%20R1%5B%22%E5%8C%BA%E5%86%85%E8%B7%AF%E7%94%B1%E5%99%A8%E6%94%B6%20Type4%22%5D%0A%20%20R1%20--%3E%20SPF%5B%22%E5%8C%BA%E5%86%85%E7%94%A8%20Type1%2F2%20%E7%AE%97%E5%88%B0%20ABR%20%E7%9A%84%E8%B7%AF%22%5D%0A%20%20SPF%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%E8%A1%A8%EF%BC%9A%E5%8C%BA%E5%86%85%E6%AE%B5%20%2B%20%E6%B1%87%E6%80%BB%E6%AE%B5%20%2B%20%E5%A4%96%E9%83%A8%E6%AE%B5%22%5D%0A%20%20STUB%5B%22%E8%8B%A5%20Area%201%20%E6%98%AF%20stub%22%5D%20--%3E%7C%22%E6%94%B6%E4%B8%8D%E5%88%B0%20Type5%22%7C%20DEF%5B%22ABR%20%E5%8F%AA%E6%B3%A8%E5%85%A5%E4%B8%80%E6%9D%A1%E9%BB%98%E8%AE%A4%E8%B7%AF%E7%94%B1%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">术语翻译：ABR 是区域边界路由器，一头连骨干区一头连普通区，跨区的账单（Type 3）由它开；ASBR 是把 OSPF 之外的路由（比如 BGP 学来的）引进来的入口，外部门票（Type 5）由它开。</span></p><p><span class="marginnote">常见误区：初学者容易以为划了区域后流量必须绕道骨干区。实际上区域只限制 LSA 洪泛与 SPF 计算范围，数据包仍按路由直发；只有汇总配置出错形成黑洞时，才会出现多余的绕行。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 OSPF-TE 的全部子 TLV。IS-IS 是下一课。后课默认：OSPF 可扩展性靠区域与 LSA 分层，SPF 仍在区内精确。</p><p>多区域不等于多平面流量工程；TE 后课用不同度量或 MPLS。</p><p>下一课<a href="/cs/isis">IS-IS</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>区域限制洪泛；Area 0 连接各区。</li><li>LSA 类型分工：精确、汇总、外部。</li><li>汇总是可扩展性，也可能藏黑洞。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2328；RFC 5340。</li></ul>',8))])}const m=o(n,[["render",T]]);export{f as __pageData,m as default};
